DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='shifts' AND c.relname='shifts' AND c.relrowsecurity AND c.relforcerowsecurity) THEN RAISE EXCEPTION 'shift RLS missing'; END IF; IF has_table_privilege('salekhpos_runtime','shifts.shifts','UPDATE') OR has_table_privilege('salekhpos_runtime','shifts.shifts','DELETE') THEN RAISE EXCEPTION 'unsafe shift privileges'; END IF; END $$;
